package com.vms.vendorcontractmanagement.controller; import com.vms.vendorcontractmanagement.dto.AuthDtos.*; import com.vms.vendorcontractmanagement.service.*; import jakarta.validation.*; import lombok.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") @RequiredArgsConstructor public class AuthController {final AuthService service; @PostMapping("/login") public AuthResponse login(@Valid @RequestBody LoginRequest r){return service.login(r);} @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) public AuthResponse register(@Valid @RequestBody RegisterRequest r){return service.register(r);} }
